455	    /// Tracks `fullscreenchange` instead of toggling a local flag: the user
456	    /// can exit fullscreen with Esc, and `requestFullscreen` can be rejected,
457	    /// so the document is the only reliable source of truth.
458	    pub(crate) fn register_fullscreen_change(self: &Rc<Self>) -> Option<EventListenerHandle> {
459	        let document = self.browser_window.document()?;
460	        let this = Rc::clone(self);
461	
462	        Some(EventListenerHandle::add(
463	            document.as_ref(),
464	            "fullscreenchange",
465	            move |_event: JsValue| {
466	                let is_fullscreen = this
467	                    .browser_window
468	                    .document()
469	                    .is_some_and(|document| document.fullscreen_element().is_some());
470	                this.state.borrow_mut().is_fullscreen = is_fullscreen;
471	            },
472	        ))
473	    }
