103	    fn register_click(&mut self, position: Point<Pixels>, time: f64) -> usize {
104	        let distance = ((f32::from(position.x) - f32::from(self.last_position.x)).powi(2)
105	            + (f32::from(position.y) - f32::from(self.last_position.y)).powi(2))
106	        .sqrt();
107	
108	        if (time - self.last_time) < 400.0 && distance < 5.0 {
109	            self.current_count += 1;
110	        } else {
111	            self.current_count = 1;
112	        }
113	
114	        self.last_position = position;
115	        self.last_time = time;
116	        self.current_count
117	    }
118	}
