187	    fn register_pointer_down(self: &Rc<Self>) -> EventListenerHandle {
188	        let this = Rc::clone(self);
189	        self.listen("pointerdown", move |event: JsValue| {
190	            let event: web_sys::PointerEvent = event.unchecked_into();
191	            event.prevent_default();
192	            this.input_element.focus().ok();
193	
194	            // Capture the pointer so drags that leave the canvas keep
195	            // delivering pointermove/pointerup here; otherwise a release
196	            // outside the canvas is never seen and `pressed_button` stays
197	            // stuck. The capture is released implicitly on pointerup.
198	            this.canvas.set_pointer_capture(event.pointer_id()).ok();
