205	            this.pressed_button.set(Some(button));
206	            let click_count = this.click_state.borrow_mut().register_click(position, time);
207	
208	            {
209	                let mut current_state = this.state.borrow_mut();
210	                current_state.mouse_position = position;
211	                current_state.modifiers = modifiers;
212	            }
213	
214	            this.dispatch_input(PlatformInput::MouseDown(MouseDownEvent {
215	                button,
216	                position,
217	                modifiers,
218	                click_count,
219	                first_mouse: false,
220	            }));
