372	            let capslock = capslock_from_keyboard_event(&event);
373	
374	            if this.update_modifiers(modifiers, capslock) {
375	                this.dispatch_input(PlatformInput::ModifiersChanged(ModifiersChangedEvent {
376	                    modifiers,
377	                    capslock,
378	                }));
379	            }
380	
381	            let key = dom_key_to_gpui_key(&event);
382	
383	            if is_modifier_only_key(&key) {
384	                return;
385	            }
386	
387	            let is_held = event.repeat();
388	            let key_char = compute_key_char(&event, &key, &modifiers);
389	
390	            let keystroke = Keystroke {
391	                modifiers,
392	                key,
393	                key_char: key_char.clone(),
394	            };
395	
396	            let result = this.dispatch_input(PlatformInput::KeyDown(KeyDownEvent {
397	                keystroke,
398	                is_held,
399	                prefer_character_input: false,
400	            }));
401	
402	            if let Some(result) = result {
403	                if !result.propagate {
404	                    event.prevent_default();
405	                    return;
406	                }
407	            }
408	
409	            if this.is_composing.get() || event.is_composing() {
410	                event.prevent_default();
411	                return;
412	            }
413	
414	            if keystroke_inserts_text(&modifiers, this.is_mac)
415	                && let Some(text) = key_char
416	            {
417	                this.with_input_handler(|handler| {
418	                    handler.replace_text_in_range(None, &text);
419	                });
420	                // The character went into the input handler; suppress browser
421	                // side-effects for the same keystroke (space scrolling the
422	                // page, quick-find, etc.). Everything not handled above falls
423	                // through so browser shortcuts keep their defaults.
424	                event.prevent_default();
425	            }
426	        })
427	    }
