467	    /// Paste is delivered through the DOM `paste` event rather than
468	    /// `Platform::read_from_clipboard`: the browser's asynchronous clipboard
469	    /// read API cannot fit that synchronous signature, while `ClipboardEvent`
470	    /// exposes `clipboardData` synchronously inside the event. It fires for
471	    /// any browser-initiated paste (keyboard, menu bar, context menu).
472	    ///
473	    /// Text-only pastes reach the input handler synchronously. Pasted image
474	    /// files only expose their bytes through asynchronous blob reads, so
475	    /// pastes containing images are delivered once those reads resolve — to
476	    /// whichever input handler is focused at that point, matching how an
477	    /// application-level paste action would behave.
478	    fn register_paste(self: &Rc<Self>) -> EventListenerHandle {
479	        let this = Rc::clone(self);
480	        self.listen_input("paste", move |event: JsValue| {
481	            let event: web_sys::ClipboardEvent = event.unchecked_into();
482	            let Some(clipboard_data) = event.clipboard_data() else {
483	                return;
484	            };
485	            let text = clipboard_data
486	                .get_data("text/plain")
487	                .ok()
488	                .filter(|text| !text.is_empty());
489	
490	            // File handles must be collected synchronously: the browser
491	            // clears `clipboardData`'s item list once this handler returns,
492	            // while the `File`s themselves stay readable afterwards.
493	            let mut image_files = Vec::new();
494	            let items = clipboard_data.items();
495	            for index in 0..items.length() {
496	                let Some(item) = items.get(index) else {
497	                    continue;
498	                };
499	                if item.kind() != "file" {
500	                    continue;
501	                }
502	                let Some(format) = ImageFormat::from_mime_type(&item.type_()) else {
503	                    continue;
504	                };
505	                if let Ok(Some(file)) = item.get_as_file() {
506	                    image_files.push((format, file));
507	                }
508	            }
509	
510	            if text.is_none() && image_files.is_empty() {
511	                return;
512	            }
513	            event.prevent_default();
514	
515	            if image_files.is_empty() {
516	                if let Some(text) = text {
517	                    this.with_input_handler(|handler| {
518	                        handler.paste(ClipboardItem::new_string(text));
519	                    });
520	                }
521	                return;
522	            }
523	
524	            let this = Rc::clone(&this);
525	            wasm_bindgen_futures::spawn_local(async move {
526	                let mut entries = Vec::new();
527	                if let Some(text) = text {
528	                    entries.push(ClipboardEntry::String(ClipboardString::new(text)));
529	                }
530	                for (format, file) in image_files {
531	                    match crate::platform::read_blob_bytes(&file).await {
532	                        Ok(bytes) => {
533	                            entries.push(ClipboardEntry::Image(Image::from_bytes(format, bytes)));
534	                        }
535	                        Err(error) => {
536	                            log::error!(
537	                                "failed to read pasted image: {}",
538	                                crate::platform::js_error_message(&error)
539	                            );
540	                        }
541	                    }
542	                }
543	                if entries.is_empty() {
544	                    return;
545	                }
546	                this.with_input_handler(|handler| {
547	                    handler.paste(ClipboardItem { entries });
548	                });
549	            });
550	        })
551	    }
