629	fn dom_key_to_gpui_key(event: &web_sys::KeyboardEvent) -> String {
630	    let key = event.key();
631	    match key.as_str() {
632	        "Enter" => "enter".to_string(),
633	        "Backspace" => "backspace".to_string(),
634	        "Tab" => "tab".to_string(),
635	        "Escape" => "escape".to_string(),
636	        "Delete" => "delete".to_string(),
637	        " " => "space".to_string(),
638	        "ArrowLeft" => "left".to_string(),
639	        "ArrowRight" => "right".to_string(),
640	        "ArrowUp" => "up".to_string(),
641	        "ArrowDown" => "down".to_string(),
642	        "Home" => "home".to_string(),
643	        "End" => "end".to_string(),
644	        "PageUp" => "pageup".to_string(),
645	        "PageDown" => "pagedown".to_string(),
646	        "Insert" => "insert".to_string(),
647	        "Control" => "control".to_string(),
648	        "Alt" => "alt".to_string(),
649	        "Shift" => "shift".to_string(),
650	        "Meta" => "platform".to_string(),
651	        "CapsLock" => "capslock".to_string(),
652	        other => {
653	            if let Some(rest) = other.strip_prefix('F') {
654	                if let Ok(number) = rest.parse::<u8>() {
655	                    if (1..=35).contains(&number) {
656	                        return format!("f{number}");
657	                    }
658	                }
659	            }
660	            other.to_lowercase()
661	        }
662	    }
663	}
