713	pub(crate) fn is_mac_platform(browser_window: &web_sys::Window) -> bool {
714	    let navigator = browser_window.navigator();
715	
716	    #[allow(deprecated)]
717	    // navigator.platform() is deprecated but navigator.userAgentData is not widely available yet
718	    if let Ok(platform) = navigator.platform() {
719	        if platform.contains("Mac") {
720	            return true;
721	        }
722	    }
723	
724	    if let Ok(user_agent) = navigator.user_agent() {
725	        return user_agent.contains("Mac");
726	    }
727	
728	    false
729	}
