731	fn is_modifier_only_key(key: &str) -> bool {
732	    matches!(
733	        key,
734	        "control" | "alt" | "shift" | "platform" | "capslock" | "compose" | "process"
735	    )
736	}
737	
738	/// Whether a keystroke with these modifiers produces text to insert.
739	///
740	/// On macOS, Option participates in text entry (e.g. option-n composes "~"
741	/// or accented characters), so only Command and Control disqualify. Elsewhere,
742	/// plain Alt is a shortcut modifier, but AltGr is reported by browsers as
743	/// control+alt and `event.key()` then carries the composed character.
744	fn keystroke_inserts_text(modifiers: &Modifiers, is_mac: bool) -> bool {
745	    if is_mac {
746	        !modifiers.platform && !modifiers.control
747	    } else {
748	        modifiers.is_subset_of(&Modifiers::shift()) || (modifiers.control && modifiers.alt)
749	    }
750	}
751	
752	fn compute_key_char(
753	    event: &web_sys::KeyboardEvent,
754	    gpui_key: &str,
755	    modifiers: &Modifiers,
756	) -> Option<String> {
757	    // AltGr arrives as control+alt with the composed character in
758	    // `event.key()`; bare Command/Control combinations are not text.
759	    if (modifiers.platform || modifiers.control) && !(modifiers.control && modifiers.alt) {
760	        return None;
761	    }
762	
763	    if is_modifier_only_key(gpui_key) {
764	        return None;
765	    }
766	
767	    if gpui_key == "space" {
768	        return Some(" ".to_string());
769	    }
770	
771	    let raw_key = event.key();
772	
773	    if raw_key.len() == 1 {
774	        return Some(raw_key);
775	    }
776	
777	    None
778	}
779	
780	fn pointer_position_in_element(event: &web_sys::PointerEvent) -> Point<Pixels> {
781	    let mouse_event: &web_sys::MouseEvent = event.as_ref();
782	    mouse_position_in_element(mouse_event)
783	}
784	
785	fn mouse_position_in_element(event: &web_sys::MouseEvent) -> Point<Pixels> {
786	    // offset_x/offset_y give position relative to the target element's padding edge
787	    point(px(event.offset_x() as f32), px(event.offset_y() as f32))
788	}
789

